price = {}
for bd, v in sched.items():
    cnt = (v['mature'] or 0) + (v['immature'] or 0)
    price[bd] = (v['mrr'] or 0) / cnt if cnt else 22.0

# ---- Cost model (measured wk21) ----
COMPUTE_PER_SUB = 0.181   # 342111/7/269931
CAP_COST = 28000          # T6
LEADACQ = 0.5
DEV = 1000.0
NEW_PRICE = 21.0
NEW_SIGNUP = 16.5         # first-period w/ $8 lead promo, blended
CONV = 0.81

# ---- Ad calibration to CURRENT observed rates ----
# content 48.87/1k, referral 41.75/1k, organic 1514/day, all at current S1 headroom
def make_rates(cap):
    head_now = max(1.0, (cap - S1_SUBS)/1000.0)   # k-subs
    return (48.87/head_now, 41.75/head_now, 1514.0/head_now)  # KC, KR, ORG per k-head

def cap_k(day, cap):
    return (cap/1000.0) * (1 + 0.00026*(day-DAY0))  # ~9.6%/yr cap growth

def run(cap, churn1, churn_sub, ads_fn, ops_fn,
        harv_start=9999, harv_end=9999, harv_mult=1.0, harv_churn=0.0,
        label='', debug=False):
    KC, KR, ORG = make_rates(cap)
    cohorts = []
    for bd, v in sched.items():
        nr = 148 + ((bd-148) % 30)
        if v['mature']:   cohorts.append([nr, float(v['mature']),   price[bd], 1])
        if v['immature']: cohorts.append([nr, float(v['immature']), price[bd], 0])
    cash = CASH0
    out = {DAY0: cash}
    wk = {'rec':0.0,'sig':0.0,'cost':0.0,'canc':0.0}
    for day in range(DAY0+1, DAY0+366):
        if day < harv_start: hf, hc = 1.0, 0.0
        elif day < harv_end:
            frac = (day-harv_start)/max(1,(harv_end-harv_start))
            hf = 1.0 + (harv_mult-1.0)*frac
            hc = harv_churn
        else:
            hf, hc = harv_mult, 0.0
        rev = 0.0; canc = 0.0
        for c in cohorts:
            if c[0] == day:
                ch = (churn1 if c[3]==0 else churn_sub) + hc
                canc += c[1]*ch
                c[1] *= (1-ch)
                rev += c[1]*c[2]*hf
                c[0] = day+30
                c[3] += 1
        subs = sum(c[1] for c in cohorts)
        head = max(0.0, cap_k(day,cap) - S1_SUBS/1000.0 - (subs-SUBS0)/1000.0)
        content_sp, ref_sp = ads_fn(day, head)
        leads = (KC*head)*(content_sp/1000.0) + (KR*head)*(ref_sp/1000.0) + ORG*head
        new = leads * CONV
        new = max(0.0, min(new, cap_k(day,cap)*1000.0 - subs))
