    head_now = max(1.0, (cap - S1_SUBS)/1000.0)
    return (48.87/head_now, 41.75/head_now, 1514.0/head_now)

def cap_k(day, cap):
    return (cap/1000.0) * (1 + 0.00026*(day-DAY0))

def run(cap, mega_churn, later_churn1, churn_mat, ads_fn, ops_fn,
        harv_start=9999, harv_end=9999, harv_mult=1.0, harv_churn=0.0,
        debug=False):
    KC, KR, ORG = make_rates(cap)
    cohorts = []  # [next_rebill_day, count, price, num_rebills_done, first_rebill_churn]
