        CONV=0.88, org_mult=1.0, debug=False):
    def cap_k(day): return (cap/1000.0)*(1 + cap_growth*(day-DAY0))
    head0 = max(1.0, (cap - S1_SUBS0)/1000.0)
    KC, KR = CONTENT_EFF/head0, REF_EFF/head0
    ORG = ORG_LEADS*org_mult/head0
    cohorts = []  # [next_bill_day, count, price, first_rebill_churn, num_rebills]
    for bd, mix in mature.items():
        nd = DAY0+1 + ((bd - (DAY0+1)) % 30)
        cohorts.append([nd, float(sum(mix.values())), blended(mix), mat_churn, 1])
    for sd, mix in immature.items():
        cohorts.append([sd+30, float(sum(mix.values())), blended(mix),
                        min(0.95, churn1(sd)*churn_mult), 0])
    cash = CASH0
    out = {DAY0: cash}
    wk = {'rec':0,'sig':0,'cost':0,'canc':0,'new':0}
    for day in range(DAY0+1, DAY0+366):
        rev = 0.0
        for c in cohorts:
            if c[0] == day:
                ch = c[3] if c[4]==0 else mat_churn
                c[1] *= (1-ch)
                rev += c[1]*c[2]
                c[0] = day+30; c[4] += 1
                wk['canc'] += 0  # tracked implicitly
        subs = sum(c[1] for c in cohorts)
        head = max(0.0, cap_k(day) - subs/1000.0)
        csp, rsp = ads_fn(day, head)
        leads = (KC*head)*(csp/1000.0) + (KR*head)*(rsp/1000.0) + ORG*head
        new = leads*CONV
        new = max(0.0, min(new, cap_k(day)*1000.0 - subs))
        signup = new*NEW_SIGNUP
        cohorts.append([day+30, new, NEW_PRICE, churn1(day), 0])
        cost = csp+rsp + ops + COMPUTE_PER_SUB*subs + CAP_COST + DEV + LEADACQ*leads
        cash += rev + signup - cost
        out[day] = cash
        wk['rec']+=rev; wk['sig']+=signup; wk['cost']+=cost; wk['new']+=new
        if debug and (day-DAY0)%7==0:
            print(f"   d{day}: subs={subs:>9,.0f} head={head:4.1f}k rec7d=${wk['rec']:>10,.0f} "
                  f"sig=${wk['sig']:>8,.0f} new={wk['new']:>7,.0f} "
                  f"cost=${wk['cost']:>10,.0f} cash=${cash:>13,.0f}")
            wk = {'rec':0,'sig':0,'cost':0,'new':0,'canc':0}
    return out

def ads_hold(day, head):  # ~$30k/day
    if head > 40: return (27000.0, 3000.0)
    if head > 25: return (22000.0, 2000.0)
    if head > 12: return (14000.0, 1000.0)
    return (6000.0, 0.0)
def ads_bear(day, head):
    if head > 30: return (24000.0, 2000.0)
    if head > 15: return (15000.0, 1000.0)
    return (5000.0, 0.0)
def ads_bull(day, head):
    if head > 45: return (28000.0, 3000.0)
    if head > 22: return (22000.0, 2000.0)
    if head > 10: return (14000.0, 1000.0)
    return (6000.0, 0.0)

