        print(f" d{D}: cash={v[0]:,} base={v[1]:,} ops={v[2]:,} cap={v[3]:,}")

# to day 504 for endgame
print("\n=== TO DAY 504 (adaptive) ===")
for name,ch,npd,dec in [('BASE',BASE,750,0.02),('BEAR',BEAR,600,0.03),('HARSH',HARSH,500,0.04),('BULL',BULL,1100,0.0)]:
    s=run(ch,npd,dec,adaptive_ops=True,days=294)
