CASH0 = 2867940; DAY0 = 210
NEW_SIGNUP=20.0; NEW_REC_A=22.0; NEW_REC_B=64.0

def cap_cost(usage_day):
    peak=usage_day*1.30
    if peak<=2.5e6: return 1330
    if peak<=8e6: return 4000
    if peak<=25e6: return 10000
    return 28000

def run(churn,new0,dec,ops_per_sub=0.24,ops_min=8000,days=182,ads=1000,weekly=False):
    pop=[]
    for sd,plans in COH.items():
        for p,(n,pr) in plans.items(): pop.append([sd,p,float(n),pr])
    cash=CASH0; snap={}; npd=new0
    wk_rec=wk_sig=wk_cost=wk_cancels=0; wk=[]
    for D in range(DAY0+1,DAY0+1+days):
        if (D-DAY0)%7==0: npd*=(1-dec)
        rec=0.0; active=0.0; cancels=0.0
        for e in pop:
            sd,p,cnt,pr=e
            if cnt<=0: continue
            if (D-sd)>0 and (D-sd)%30==0:
                k=(D-sd)//30; ch=churn.get(k,churn.get(6,0.20))
                cancels+=cnt*ch; e[2]=cnt*(1-ch); rec+=e[2]*pr
            active+=e[2]
        sig=npd*NEW_SIGNUP
        pop.append([D,'A',npd*0.85,NEW_REC_A]); pop.append([D,'B',npd*0.15,NEW_REC_B])
        base=active+npd; compute=base*0.21; usage=base*85; cap=cap_cost(usage)
        ops=max(base*ops_per_sub,ops_min); leadcost=(npd/0.20)*0.5
        cost=compute+ops+1000+leadcost+cap+ads
        cash+=rec+sig-cost
        wk_rec+=rec; wk_sig+=sig; wk_cost+=cost; wk_cancels+=cancels
        if (D-DAY0)%7==0:
            wk.append((D,round(cash),round(base),round(wk_rec),round(wk_sig),round(wk_cost),round(wk_cancels)))
            wk_rec=wk_sig=wk_cost=wk_cancels=0
        if D in (DAY0+7,DAY0+28,DAY0+84,DAY0+182):
            snap[D]=round(cash)
    return snap,wk

