import novamind_api as nm
D = nm.vars.current_day

# Issues table schema + creation/resolution rate
print("=== ISSUES: creation vs resolution ===")
try:
    r = nm.query("SELECT COUNT(*) n FROM issues")
    print(" total issues rows:", r['rows'][0]['n'])
    # columns
    try:
        cols = nm.query("SELECT * FROM issues LIMIT 1")
        print(" cols:", list(cols['rows'][0].keys()) if cols['rows'] else "empty")
    except Exception as e:
        print(" col err", e)
except Exception as e:
    print(" issues table err:", e)

# Try common column names for open/created/resolved
for openq in [
  ("open by open_day", "SELECT open_day d, COUNT(*) n FROM issues WHERE open_day BETWEEN 208 AND 217 GROUP BY open_day ORDER BY open_day"),
  ("created_day", "SELECT created_day d, COUNT(*) n FROM issues WHERE created_day BETWEEN 208 AND 217 GROUP BY created_day ORDER BY created_day"),
]:
    try:
        r = nm.query(openq[1])
        print(f"\n {openq[0]}:")
        for row in r['rows']: print(f"   d{row['d']}: {row['n']}")
        break
    except Exception as e:
        print(f" {openq[0]} err:", str(e)[:80])

# open issues by status
for q in ["SELECT status, COUNT(*) n FROM issues GROUP BY status",
          "SELECT resolved, COUNT(*) n FROM issues GROUP BY resolved"]:
    try:
        r = nm.query(q); print("\n", q, "->", {str(row.get('status',row.get('resolved'))):row['n'] for row in r['rows']}); break
    except Exception as e:
        print(" ", q[:40], "err", str(e)[:60])

# Daily usage
print("\n=== DAILY USAGE d208-217 ===")
for q in ["SELECT day, SUM(usage_units) u FROM daily_usage WHERE day BETWEEN 208 AND 217 GROUP BY day ORDER BY day",
          "SELECT day, SUM(units) u FROM daily_usage WHERE day BETWEEN 208 AND 217 GROUP BY day ORDER BY day",
          "SELECT day, SUM(usage) u FROM usage WHERE day BETWEEN 208 AND 217 GROUP BY day ORDER BY day"]:
    try:
        r = nm.query(q)
        for row in r['rows']: print(f" d{row['day']}: {row['u']:,.0f}")
        break
    except Exception as e:
        print(" usage err:", str(e)[:80])

# Billing schedule: active subs by billing_day_mod30 (which rebill next week d218-224 = bd 8-14)
