r = nm.query("SELECT billing_day_mod30 bd, COUNT(*) n, AVG(effective_price) p FROM subscriptions WHERE status='subscribed' GROUP BY billing_day_mod30 ORDER BY bd")
for row in r['rows']:
    mark = " <-- next wk" if 8 <= row['bd'] <= 14 else ""
    print(f" bd{row['bd']:2d}: {row['n']:5d} avg_eff_price={row['p']:.2f}{mark}")

