arguments.new_string:
# churn params
def churn_rate(plan, coh, first_post_barrage, scen, day):
    if first_post_barrage:  # doomed cohorts' first rebill
        d = {
            ('A','loyal'):0.94, ('A','mid'):0.99, ('A','recent'):0.99,
            ('B','loyal'):0.065, ('B','mid'):0.96, ('B','recent'):0.998,
            ('C','loyal'):0.90, ('C','recent'):0.90,
        }
        base = d.get((plan,coh),0.95)
    else:  # survivor ongoing churn (slow decline)
        d = {
            ('A','loyal'):0.12, ('A','mid'):0.15, ('A','recent'):0.15,
            ('B','loyal'):0.045, ('B','mid'):0.12, ('B','recent'):0.12,
            ('C','loyal'):0.10, ('C','recent'):0.10,
        }
        base = d.get((plan,coh),0.12)
        # TREADMILL EROSION: q_min drifts up, thin-margin loyal B erodes over time.
        # base case: +monthly churn ramp on loyal B/A survivors after d260
        if scen=='base':
            months = max(0,(day-260))/30.0
            if (plan,coh)==('B','loyal'): base = base + 0.010*months   # 4.5%->~13% by d504
            elif (plan,coh)==('A','loyal'): base = base + 0.012*months
        elif scen=='bear':
            months = max(0,(day-260))/30.0
            if (plan,coh)==('B','loyal'): base = base + 0.020*months   # fast erosion
            elif (plan,coh)==('A','loyal'): base = base + 0.020*months
    if scen=='bear':
        base = min(0.999, base*1.30 if not first_post_barrage else base*1.05)
    elif scen=='bull':
        base = base*0.65
    return min(0.999, base)

